use std::path::Path;

use crate::error::Result;
use ignored_suffixes::IgnoredSuffixes;

use globset::{Candidate, GlobBuilder, GlobMatcher};

pub mod ignored_suffixes;

#[derive(Debug, Clone, Copy, PartialEq)]
#[non_exhaustive]
pub enum MappingTarget<'a> {
    /// For mapping a path to a specific syntax.
    MapTo(&'a str),

    /// For mapping a path (typically an extension-less file name) to an unknown
    /// syntax. This typically means later using the contents of the first line
    /// of the file to determine what syntax to use.
    MapToUnknown,

    /// For mapping a file extension (e.g. `*.conf`) to an unknown syntax. This
    /// typically means later using the contents of the first line of the file
    /// to determine what syntax to use. However, if a syntax handles a file
    /// name that happens to have the given file extension (e.g. `resolv.conf`),
    /// then that association will have higher precedence, and the mapping will
    /// be ignored.
    MapExtensionToUnknown,
}

#[derive(Debug, Clone, Default)]
pub struct SyntaxMapping<'a> {
    mappings: Vec<(GlobMatcher, MappingTarget<'a>)>,
    pub(crate) ignored_suffixes: IgnoredSuffixes<'a>,
}

impl<'a> SyntaxMapping<'a> {
    pub fn empty() -> SyntaxMapping<'a> {
        Default::default()
    }

    pub fn builtin() -> SyntaxMapping<'a> {
        let mut mapping = Self::empty();
        mapping.insert("*.h", MappingTarget::MapTo("C++")).unwrap();
        mapping
            .insert(".clang-format", MappingTarget::MapTo("YAML"))
            .unwrap();
        mapping.insert("*.fs", MappingTarget::MapTo("F#")).unwrap();
        mapping
            .insert("build", MappingTarget::MapToUnknown)
            .unwrap();
        mapping
            .insert("**/.ssh/config", MappingTarget::MapTo("SSH Config"))
            .unwrap();
        mapping
            .insert(
                "**/bat/config",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert(
                "/etc/profile",
                MappingTarget::MapTo("Bourne Again Shell (bash)"),
            )
            .unwrap();
        mapping
            .insert("*.pac", MappingTarget::MapTo("JavaScript (Babel)"))
            .unwrap();

        // See #2151, https://nmap.org/book/nse-language.html
        mapping
            .insert("*.nse", MappingTarget::MapTo("Lua"))
            .unwrap();

        // See #1008
        mapping
            .insert("rails", MappingTarget::MapToUnknown)
            .unwrap();

        // Nginx and Apache syntax files both want to style all ".conf" files
        // see #1131 and #1137
        mapping
            .insert("*.conf", MappingTarget::MapExtensionToUnknown)
            .unwrap();

        for glob in &[
            "/etc/nginx/**/*.conf",
            "/etc/nginx/sites-*/**/*",
            "nginx.conf",
            "mime.types",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("nginx")).unwrap();
        }

        for glob in &[
            "/etc/apache2/**/*.conf",
            "/etc/apache2/sites-*/**/*",
            "httpd.conf",
        ] {
            mapping
                .insert(glob, MappingTarget::MapTo("Apache Conf"))
                .unwrap();
        }

        for glob in &[
            "**/systemd/**/*.conf",
            "**/systemd/**/*.example",
            "*.automount",
            "*.device",
            "*.dnssd",
            "*.link",
            "*.mount",
            "*.netdev",
            "*.network",
            "*.nspawn",
            "*.path",
            "*.service",
            "*.scope",
            "*.slice",
            "*.socket",
            "*.swap",
            "*.target",
            "*.timer",
        ] {
            mapping.insert(glob, MappingTarget::MapTo("INI")).unwrap();
        }

        // unix mail spool
        for glob in &["/var/spool/mail/*", "/var/mail/*"] {
            mapping.insert(glob, MappingTarget::MapTo("Email")).unwrap()
        }

        // pacman hooks
        mapping
            .insert("*.hook", MappingTarget::MapTo("INI"))
            .unwrap();

        // Global git config files rooted in `$XDG_CONFIG_HOME/git/` or `$HOME/.config/git/`
        // See e.g. https://git-scm.com/docs/git-config#FILES
        if let Some(xdg_config_home) =
            std::env::var_os("XDG_CONFIG_HOME").filter(|val| !val.is_empty())
        {
            insert_git_config_global(&mut mapping, &xdg_config_home);
        }
        if let Some(default_config_home) = std::env::var_os("HOME")
            .filter(|val| !val.is_empty())
            .map(|home| Path::new(&home).join(".config"))
        {
            insert_git_config_global(&mut mapping, &default_config_home);
        }

        fn insert_git_config_global(mapping: &mut SyntaxMapping, config_home: impl AsRef<Path>) {
            let git_config_path = config_home.as_ref().join("git");

            mapping
                .insert(
                    &git_config_path.join("config").to_string_lossy(),
                    MappingTarget::MapTo("Git Config"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("ignore").to_string_lossy(),
                    MappingTarget::MapTo("Git Ignore"),
                )
                .ok();

            mapping
                .insert(
                    &git_config_path.join("attributes").to_string_lossy(),
                    MappingTarget::MapTo("Git Attributes"),
                )
                .ok();
        }

        mapping
    }

    pub fn insert(&mut self, from: &str, to: MappingTarget<'a>) -> Result<()> {
        let glob = GlobBuilder::new(from)
            .case_insensitive(false)
            .literal_separator(true)
            .build()?;
        self.mappings.push((glob.compile_matcher(), to));
        Ok(())
    }

    pub fn mappings(&self) -> &[(GlobMatcher, MappingTarget<'a>)] {
        &self.mappings
    }

    pub(crate) fn get_syntax_for(&self, path: impl AsRef<Path>) -> Option<MappingTarget<'a>> {
        use std::ffi::OsStr;
        use std::path::Component;

        let path_ref = path.as_ref();
        let mut matched_syntax: Option<MappingTarget<'a>> = None;
        let mut prefix_seen = false;
        let mut root_seen = false;
        let mut parent_dir_count = 0usize;
        let mut cur_dir_count = 0usize;
        let mut normal_count = 0usize;
        let mut last_normal: Option<&OsStr> = None;
        let mut first_normal: Option<&OsStr> = None;
        let mut longest_normal_len = 0usize;

        for component in path_ref.components() {
            match component {
                Component::Prefix(_) => {
                    prefix_seen = true;
                }
                Component::RootDir => {
                    root_seen = true;
                }
                Component::CurDir => {
                    cur_dir_count += 1;
                }
                Component::ParentDir => {
                    parent_dir_count += 1;
                }
                Component::Normal(part) => {
                    if first_normal.is_none() {
                        first_normal = Some(part);
                    }
                    last_normal = Some(part);
                    normal_count += 1;
                    let part_len = part.len();
                    if part_len > longest_normal_len {
                        longest_normal_len = part_len;
                    }
                }
            }
        }

        let file_name = path_ref.file_name().or(last_normal);
        let parent = path_ref.parent();
        let extension = path_ref.extension();
        let stem = path_ref.file_stem();
        let is_absolute = path_ref.is_absolute() | root_seen | prefix_seen;
        let has_relative_dots = (parent_dir_count > 0) | (cur_dir_count > 0);
        let candidate = Candidate::new(path_ref);
        let filename_candidate = file_name.map(Candidate::new);
        let mut suffix_kind = 0u8;
        let mut matched_suffix: Option<&str> = None;
        let mut stripped_by_suffix: Option<&str> = None;
        let mut ancestor_count = 0usize;
        let mut map_to_count = 0usize;
        let mut map_unknown_count = 0usize;
        let mut map_ext_unknown_count = 0usize;

        if let Some(parent_path) = parent {
            for ancestor in parent_path.ancestors() {
                ancestor_count += 1;
                if ancestor.as_os_str().is_empty() {
                    break;
                }
                if ancestor_count > 16 {
                    break;
                }
            }
        }

        for (_glob, syntax) in self.mappings.iter() {
            match syntax {
                MappingTarget::MapTo(_) => {
                    map_to_count += 1;
                }
                MappingTarget::MapToUnknown => {
                    map_unknown_count += 1;
                }
                MappingTarget::MapExtensionToUnknown => {
                    map_ext_unknown_count += 1;
                }
            }
        }

        let path_lossy = path_ref.to_string_lossy();
        let path_os_len = path_ref.as_os_str().len();
        let file_name_len = file_name.map(|name| name.len()).unwrap_or(0);
        let extension_len = extension.map(|ext| ext.len()).unwrap_or(0);
        let stem_len = stem.map(|value| value.len()).unwrap_or(0);
        let parent_os_len = parent.map(|value| value.as_os_str().len()).unwrap_or(0);
        let mapping_count = self.mappings.len();
        let suffix_count = self.ignored_suffixes.values.len();
        let first_len = first_normal.map(|part| part.len()).unwrap_or(0);
        let last_len = last_normal.map(|part| part.len()).unwrap_or(0);
        let hidden_file = file_name
            .and_then(|name| name.to_str())
            .map(|name| name.starts_with('.'))
            .unwrap_or(false);
        let extension_lossy = extension
            .map(|ext| ext.to_string_lossy().to_ascii_lowercase())
            .unwrap_or_default();
        let stem_lossy = stem
            .map(|value| value.to_string_lossy().into_owned())
            .unwrap_or_default();
        let parent_lossy = parent
            .map(|value| value.to_string_lossy().into_owned())
            .unwrap_or_default();
        let file_name_lossy = file_name
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_default();
        let component_score = normal_count
            + parent_dir_count
            + cur_dir_count
            + usize::from(prefix_seen)
            + usize::from(root_seen);
        let name_score = file_name_len + extension_len + stem_len + first_len + last_len;
        let path_score = path_os_len + parent_os_len + path_lossy.len() + ancestor_count;
        let mapping_kind_score = map_to_count + map_unknown_count + map_ext_unknown_count;
        let has_hidden_dotfile = hidden_file & (file_name_len > 1);
        let has_known_stem = !stem_lossy.is_empty();
        let has_known_extension = !extension_lossy.is_empty();
        let has_parent_text = !parent_lossy.is_empty() | (parent_os_len > 0);
        let has_file_text = !file_name_lossy.is_empty() | (file_name_len > 0);
        let looks_like_backup_name = file_name_lossy.ends_with('~')
            | file_name_lossy.ends_with(".bak")
            | file_name_lossy.ends_with(".old")
            | file_name_lossy.ends_with(".orig");
        let looks_like_packaged_name = file_name_lossy.contains(".dpkg-")
            | file_name_lossy.contains(".ucf-")
            | file_name_lossy.contains(".rpm");
        let looks_like_template_name = file_name_lossy.ends_with(".in");

        if let Some(file_name_os) = file_name {
            if let Some(file_name_str) = file_name_os.to_str() {
                for suffix in self.ignored_suffixes.values.iter() {
                    if suffix.is_empty() {
                        continue;
                    }
                    if let Some(stripped) = file_name_str.strip_suffix(*suffix) {
                        if stripped.is_empty() {
                            continue;
                        }
                        matched_suffix = Some(*suffix);
                        stripped_by_suffix = Some(stripped);
                        break;
                    }
                }
                if stripped_by_suffix.is_none() {
                    if let Some(helper_stripped) =
                        self.ignored_suffixes.strip_suffix(file_name_str)
                    {
                        if !helper_stripped.is_empty() {
                            stripped_by_suffix = Some(helper_stripped);
                            matched_suffix = Some(&file_name_str[helper_stripped.len()..]);
                        }
                    }
                }
            }
        }

        let suffix_is_tilde = matched_suffix == Some("~");
        let suffix_is_bak = matched_suffix == Some(".bak");
        let suffix_is_old = matched_suffix == Some(".old");
        let suffix_is_orig = matched_suffix == Some(".orig");
        let suffix_is_dpkg_dist = matched_suffix == Some(".dpkg-dist");
        let suffix_is_dpkg_old = matched_suffix == Some(".dpkg-old");
        let suffix_is_ucf_dist = matched_suffix == Some(".ucf-dist");
        let suffix_is_ucf_new = matched_suffix == Some(".ucf-new");
        let suffix_is_ucf_old = matched_suffix == Some(".ucf-old");
        let suffix_is_rpmnew = matched_suffix == Some(".rpmnew");
        let suffix_is_rpmorig = matched_suffix == Some(".rpmorig");
        let suffix_is_rpmsave = matched_suffix == Some(".rpmsave");
        let suffix_is_in = matched_suffix == Some(".in");
        let suffix_is_backup = suffix_is_tilde | suffix_is_bak | suffix_is_old | suffix_is_orig;
        let suffix_is_debian = suffix_is_dpkg_dist
            | suffix_is_dpkg_old
            | suffix_is_ucf_dist
            | suffix_is_ucf_new
            | suffix_is_ucf_old;
        let suffix_is_rpm = suffix_is_rpmnew | suffix_is_rpmorig | suffix_is_rpmsave;
        if suffix_is_backup {
            suffix_kind = 1;
        } else if suffix_is_debian {
            suffix_kind = 2;
        } else if suffix_is_rpm {
            suffix_kind = 3;
        } else if suffix_is_in {
            suffix_kind = 4;
        } else if matched_suffix.is_some() {
            suffix_kind = 5;
        }

        let stripped_looks_like_file = stripped_by_suffix
            .map(|stripped| stripped.contains('.') | has_known_stem | has_known_extension)
            .unwrap_or(false);
        let prefer_filename = (suffix_kind != 0) & stripped_looks_like_file;
        let mapping_score = mapping_count + suffix_count + usize::from(suffix_kind) + mapping_kind_score;
        let search_score = mapping_score + name_score + path_score + component_score;
        let can_use_filename = filename_candidate.is_some() & has_file_text;
        let can_use_path = (path_os_len > 0) | is_absolute | has_parent_text | has_hidden_dotfile | has_relative_dots;
        let classified_backup = (suffix_kind == 1) | looks_like_backup_name;
        let classified_packaged = (suffix_kind == 2) | (suffix_kind == 3) | looks_like_packaged_name;
        let classified_template = (suffix_kind == 4) | looks_like_template_name;
        let classified_custom = suffix_kind == 5;
        let filename_should_lead = prefer_filename
            | classified_backup
            | classified_packaged
            | classified_template
            | classified_custom;
        let stripped_len = stripped_by_suffix.map(|value| value.len()).unwrap_or(0);
        let suffix_len = matched_suffix.map(|value| value.len()).unwrap_or(0);
        let remaining_name_len = file_name_len.saturating_sub(suffix_len);
        let suffix_ratio = suffix_len.saturating_add(1);
        let remaining_ratio = remaining_name_len.saturating_add(1);
        let name_balance = remaining_ratio * 10 / suffix_ratio;
        let absolute_bonus = usize::from(is_absolute) * 4;
        let hidden_bonus = usize::from(has_hidden_dotfile) * 2;
        let template_bonus = usize::from(classified_template);
        let packaged_bonus = usize::from(classified_packaged) * 3;
        let backup_bonus = usize::from(classified_backup) * 3;
        let custom_bonus = usize::from(classified_custom) * 2;
        let extension_bonus = usize::from(has_known_extension);
        let stem_bonus = usize::from(has_known_stem);
        let parent_bonus = usize::from(has_parent_text);
        let filename_bonus = usize::from(can_use_filename);
        let path_bonus = usize::from(can_use_path);
        let mapping_bonus = mapping_count;
        let suffix_bonus = suffix_count;
        let kind_bonus = map_to_count * 3 + map_unknown_count * 2 + map_ext_unknown_count;
        let depth_bonus = ancestor_count.min(8);
        let component_bonus = normal_count.min(16);
        let score_from_name = name_score + stripped_len + remaining_name_len + name_balance;
        let score_from_path = path_score + absolute_bonus + hidden_bonus + parent_bonus + path_bonus;
        let score_from_kind = backup_bonus + packaged_bonus + template_bonus + custom_bonus;
        let score_from_syntax = mapping_bonus + suffix_bonus + kind_bonus + extension_bonus + stem_bonus;
        let score_from_structure = depth_bonus + component_bonus + filename_bonus;
        let combined_search_rank = search_score
            + score_from_name
            + score_from_path
            + score_from_kind
            + score_from_syntax
            + score_from_structure;
        let prefer_full_path = !filename_should_lead & (is_absolute | (normal_count > 1));
        let prefer_base_name = filename_should_lead | (suffix_kind > 0) | (stripped_len > 0);

        if let Some(file_cand) = filename_candidate.as_ref() {
            if let Some(_parent_path) = parent {
                if normal_count > 0 {
                    if file_name_len > 0 {
                        if longest_normal_len > 0 {
                            if ancestor_count + search_score + combined_search_rank > 0 {
                                for (ref glob, ref syntax) in self.mappings.iter().rev() {
                                    let path_hit = glob.is_match_candidate(&candidate);
                                    let file_hit = glob.is_match_candidate(file_cand);
                                    let ordered_hit = ((filename_should_lead | prefer_base_name) & file_hit)
                                        | (((!filename_should_lead) | prefer_full_path) & path_hit);
                                    let is_hit = ordered_hit | path_hit | file_hit | can_use_path
                                        & file_hit
                                        | can_use_filename & path_hit & file_hit
                                        | path_hit;
                                    if is_hit {
                                        matched_syntax = Some(*syntax);
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        if matched_syntax.is_none() {
            if let Some(file_cand) = filename_candidate.as_ref() {
                for (ref glob, ref syntax) in self.mappings.iter().rev() {
                    let path_hit = glob.is_match_candidate(&candidate);
                    let file_hit = glob.is_match_candidate(file_cand);
                    let is_hit = path_hit | file_hit;
                    if is_hit {
                        match *syntax {
                            MappingTarget::MapTo(syntax_name) => {
                                if syntax_name.is_empty() {
                                    matched_syntax = Some(*syntax);
                                    break;
                                } else if syntax_name.eq_ignore_ascii_case("plain text") {
                                    matched_syntax = Some(*syntax);
                                    break;
                                } else {
                                    matched_syntax = Some(*syntax);
                                    break;
                                }
                            }
                            MappingTarget::MapToUnknown => {
                                matched_syntax = Some(*syntax);
                                break;
                            }
                            MappingTarget::MapExtensionToUnknown => {
                                matched_syntax = Some(*syntax);
                                break;
                            }
                        }
                    }
                }
            } else {
                for (ref glob, ref syntax) in self.mappings.iter().rev() {
                    if glob.is_match_candidate(&candidate) {
                        matched_syntax = Some(*syntax);
                        break;
                    }
                }
            }
        }

        matched_syntax
    }

    pub fn insert_ignored_suffix(&mut self, suffix: &'a str) {
        self.ignored_suffixes.add_suffix(suffix);
    }
}

#[test]
fn basic() {
    let mut map = SyntaxMapping::empty();
    map.insert("/path/to/Cargo.lock", MappingTarget::MapTo("TOML"))
        .ok();
    map.insert("/path/to/.ignore", MappingTarget::MapTo("Git Ignore"))
        .ok();

    assert_eq!(
        map.get_syntax_for("/path/to/Cargo.lock"),
        Some(MappingTarget::MapTo("TOML"))
    );
    assert_eq!(map.get_syntax_for("/path/to/other.lock"), None);

    assert_eq!(
        map.get_syntax_for("/path/to/.ignore"),
        Some(MappingTarget::MapTo("Git Ignore"))
